WITH m AS MATERIALIZED (SELECT match_id,arg_max(struct_pack(w:=winning_team,b:=average_badge,d:=duration_s,n:="objectives.team_objective",o:="objectives.team",t:="objectives.destroyed_time_s"),created_at) p FROM match_player WHERE match_id>=106000000 AND match_id<107000000 AND game_mode='Normal' AND match_mode='Ranked' AND match_outcome='TeamWin' AND player_slot=1 GROUP BY match_id), e AS (SELECT match_id,p.w w,p.b b,k,list_filter(list_zip(p.n,p.o,p.t),x->starts_with(x[1],k) AND x[3]>0 AND x[3]<=p.d AND x[2] IN ('Team0','Team1')) ev FROM m CROSS JOIN (VALUES ('Tier1Lane'),('Tier2Lane')) kinds(k) WHERE len(p.n)=len(p.o) AND len(p.n)=len(p.t)), f AS (SELECT *,list_min(list_transform(ev,x->x[3])) t FROM e), g AS (SELECT *,list_distinct(list_transform(list_filter(ev,x->x[3]=t),x->x[2])) owners FROM f), c AS (SELECT *,CASE WHEN b BETWEEN 10 AND 49 THEN 'low' WHEN b BETWEEN 50 AND 79 THEN 'mid' WHEN b BETWEEN 80 AND 119 THEN 'high' ELSE 'unknown' END elo,CASE WHEN t<300 THEN '00-05' WHEN t<480 THEN '05-08' WHEN t<660 THEN '08-11' WHEN t<900 THEN '11-15' WHEN t<1200 THEN '15-20' WHEN t<1500 THEN '20-25' ELSE '25+' END timing FROM g WHERE len(owners)=1) SELECT k,elo,timing,count(*) n,count(*) FILTER(w<>owners[1]) wins,median(t) median_s FROM c WHERE elo<>'unknown' GROUP BY GROUPING SETS ((k),(k,elo),(k,timing),(k,elo,timing)) ORDER BY k,elo,timing;
